// Returns the sidebar/login logo markup — a custom uploaded logo if the admin set one
// in Settings > Branding, otherwise the built-in Align360 mark (theme-aware dark/light pair).
function brandLogoImgHtml(px){
  if(state.settings.logoDataUrl){
    return `<img src="${state.settings.logoDataUrl}" style="height:${px}px;width:auto;max-width:220px;display:block;object-fit:contain;" alt="Logo">`;
  }
  return `<img src="${DEFAULT_LOGO_DARK}" class="logo-dark" style="height:${px}px;width:auto;display:block;" alt="Align360">` +
         `<img src="${DEFAULT_LOGO_LIGHT}" class="logo-light" style="height:${px}px;width:auto;display:none;" alt="Align360">`;
}

