/* ---------------- Storage: local fallback (window.storage / localStorage) ---------------- */
// window.storage only exists inside the Claude.ai artifact viewer. If this file
// is downloaded and opened directly in a browser (double-click / file://),
// that API isn't there — so we fall back to localStorage, and each mode
// falls back to the other if it throws, to survive either environment.
const hasWindowStorage = (typeof window !== "undefined") && !!window.storage && typeof window.storage.get === "function";
async function persistLoad(){
  if(hasWindowStorage){
    try{
      const res = await window.storage.get(STORAGE_KEY, false);
      if(res && res.value) return res.value;
    }catch(e){ /* fall through to localStorage */ }
  }
  try{ return localStorage.getItem(STORAGE_KEY); }catch(e){ return null; }
}
async function persistSave(json){
  if(hasWindowStorage){
    try{ await window.storage.set(STORAGE_KEY, json, false); return true; }
    catch(e){ /* fall through to localStorage */ }
  }
  try{ localStorage.setItem(STORAGE_KEY, json); return true; }
  catch(e){ return false; }
}
function repairLoadedState(parsed){
  state = Object.assign(JSON.parse(JSON.stringify(DEFAULT_STATE)), parsed || {});
  state.settings = Object.assign({}, DEFAULT_STATE.settings, (parsed && parsed.settings) || {});
  if(!state.settings.metrics || !state.settings.metrics.length) state.settings.metrics = DEFAULT_STATE.settings.metrics;
  if(!state.settings.tls) state.settings.tls = [];
  state.roster.forEach(a=>{
    if(a.tlName===undefined) a.tlName = "";
    if(a.lob===undefined) a.lob = "";
    ["shiftStart","shiftEnd","break1Start","break1End","break2Start","break2End","lunchStart","lunchEnd"].forEach(f=>{
      if(a[f]===undefined){ a[f] = ""; return; }
      if(a[f] && !/^\d{1,2}:\d{2}$/.test(a[f])){
        const recovered = new Date(a[f]);
        a[f] = !isNaN(recovered) ? (String(recovered.getHours()).padStart(2,"0")+":"+String(recovered.getMinutes()).padStart(2,"0")) : "";
      }
    });
  });
  if(!state.shiftSwaps) state.shiftSwaps = [];
  if(!state.processUpdates) state.processUpdates = [];
  if(!state.auditLog) state.auditLog = [];
  if(!state.history) state.history = [];
}
async function loadFromLocalOnly(){
  try{
    const raw = await persistLoad();
    if(raw) repairLoadedState(JSON.parse(raw));
  }catch(e){ /* no saved state yet */ }
}
